    data = f.read().strip()

# Try to decode as hex
def try_hex(s):
    try:
        return binascii.unhexlify(s.encode()).decode(errors='ignore')
    except Exception:
        return None

# Try to decode as base64
def try_b64(s):
    try:
        return base64.b64decode(s.encode()).decode(errors='ignore')
    except Exception:
        return None

