    raw = binascii.unhexlify(hex_str)
    print('[*] Hex decoded:', raw)
except Exception as e:
    print('[!] Hex decode failed:', e)
    raw = b''

# Check for printable values
try:
    from string import printable
    print('Printable ASCII from hex decode:', ''.join([chr(b) if chr(b) in printable else '.' for b in raw]))
except Exception as e:
    pass

# Try base64 decode the result
try:
    b64 = b64decode(raw)
    print('[*] Base64 decoded:', b64)
except Exception as e:
    print('[!] Base64 decode failed:', e)
    b64 = b''

# Check for printable values
try:
    print('Printable ASCII from base64 decode:', ''.join([chr(b) if chr(b) in printable else '.' for b in b64]))
except Exception as e:
    pass

import re
for buf in [raw, b64]:
    m = re.search(rb'csawctf\{[^}]+\}', buf)
    if m:
